select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_ELIGIBILITY','RRL_STOCK_RESERVE_CORE','RRL_STOCK_WAVE_CMD','RRL_STOCK_WAVE_LAUNCH_CMD','RRL_STOCK_CASE_PICK_CMD','RRL_STOCK_TASK_CORE','RRL_PICKING_API') and STATUS!='VALID';
select NAME,TYPE,LINE,TEXT from USER_ERRORS where NAME in('RRL_STOCK_ELIGIBILITY','RRL_STOCK_RESERVE_CORE','RRL_STOCK_WAVE_CMD','RRL_STOCK_WAVE_LAUNCH_CMD','RRL_STOCK_CASE_PICK_CMD','RRL_STOCK_TASK_CORE','RRL_PICKING_API');
